const canvas=document.getElementById('game'),overlay=document.getElementById('overlay'),ctx=overlay.getContext('2d'),$=id=>document.getElementById(id),W=960,H=540;
let renderer;const combatAudio=new CombatAudio();
const killLines=['Back to hell!','Stay down, demon!','That’s what you get!','Burn in hell!'];
const WEAPONS=[{name:'REVOLVER',delay:.3,damage:38,cone:.065,size:330},{name:'SHOTGUN',delay:.8,damage:125,cone:.19,size:390},{name:'HEAVY MACHINE GUN',delay:.115,damage:32,cone:.08,size:440},{name:'CHAINSAW',delay:.13,damage:32,cone:.35,size:400,range:1.65,cost:0},{name:'ROCKET LAUNCHER',delay:.85,damage:120,cone:.06,size:410,projectile:'rocket',speed:11,cost:1},{name:'PLASMA RIFLE',delay:.12,damage:32,cone:.055,size:370,projectile:'plasma',speed:19,cost:1},{name:'BFG 9000',delay:2,damage:600,cone:.2,size:480,projectile:'bfg',speed:8,cost:40,ammoIndex:5}];
const exit={x:19.5,y:2.5};
let stage=0,bossAwake=false,owned=[true,true,false,false,false,false,false],playerShots=[],explosions=[],charging=null;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),angle=a=>Math.atan2(Math.sin(a),Math.cos(a));
let p,enemies=[],items=[],seals=[],shots=[],particles=[],splats=[],ammo,weapon=0,ownsHeavy=false,mode='menu',time=0,kills=0,cooldown=0,flash=0,hurt=0,notice=0,lastQuip=-10,quipIndex=-1,quipTimer=0,finalWave=false,gateProgress=0,mapShown=false,keys={},mouse={left:false,right:false},last=0,sound=true,audio;
function demon(x,y,type=0){return{x,y,z:floorAt(x,y),type,hp:[65,90,200,1800][type],cd:1+Math.random(),hit:0,a:-Math.PI/2,walk:0,moving:false,patrol:Math.random()*6}}
function reset(){
 decals=[];combatAudio.stopCinematicMusic();resetWorld();stage=0;bossAwake=false;renderer?.rebuildWorld(level,floorAt,ceilingAt);owned=[true,true,false,false,false,false,false];playerShots=[];explosions=[];charging=null;p={x:19.5,y:53.5,z:0,eyeZ:0,a:-Math.PI/2,pitch:0,hp:100};
 enemies=[[11.5,51,0],[28,52,0],[19,47,0],[8,45,1],[30,45,2],[8,38,0],[12,40,1],[28,39,2],[19,36,0],[14,22,0],[25,24,1],[32,30,2],[8,11,1],[31,11,2],[19,10,0],[15,4,1],[24,4,2],[19.5,3.5,3]].map(e=>demon(...e));
 items=[[7,53,'health'],[30,53,'ammo'],[19,49,'heavy'],[11.5,52,'chainsaw'],[7,46,'ammo'],[31,46,'health'],[12,38,'ammo'],[30,38,'ammo'],[19,36,'health'],[4,25,'ammo'],[34,16,'health'],[18,17,'rocket'],[24,31,'rockets'],[5,12,'health'],[33,12,'ammo'],[19,10,'ammo'],[12,6,'health'],[26,6,'ammo'],[12,2,'cells'],[26,2,'health'],[2.5,39.5,'plasma'],[2.5,37.5,'cells'],[38,11.5,'bfg'],[38,12.5,'cells']].map(([x,y,type])=>({x,y,type}));
 seals=[{x:7.5,y:37.5,on:true,label:'NETWORK ISOLATION'},{x:31.5,y:37.5,on:true,label:'POWER RESTORED'},{x:6.5,y:10.5,on:true,label:'CONTAINMENT OVERRIDE'}];
 shots=[];particles=[];splats=[];ammo=[64,24,0,Infinity,0,0,0];weapon=0;ownsHeavy=false;time=kills=cooldown=flash=hurt=notice=quipTimer=gateProgress=0;lastQuip=-10;finalWave=false;mapShown=false;keys={};mouse={left:false,right:false};combatAudio.stopVoice();for(let id of ['message','interact','quip'])$(id).textContent='';hud();
}
function tone(f=100,d=.1,type='sawtooth',vol=.08){if(!sound||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,f/3),audio.currentTime+d);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function tell(text){$('message').textContent=text;notice=3}
function finish(win){if(win&&mode!=='ending'&&mode!=='won'){startEnding();return}combatAudio.stopVoice();combatAudio.stopCinematicMusic();combatAudio.setGameplayActive(false);mode=win?'won':'dead';document.exitPointerLock?.();$('veil').style.display='flex';$('crosshair').style.display='none';$('interact').textContent='';document.querySelector('.eyebrow').textContent=win?'THE LAB IS FREE.':'HELL CAUGHT UP WITH YOU.';document.querySelector('h1').innerHTML=win?'CONTAINMENT<br><em>RESTORED</em>':'YOU ARE<br><em>DEAD</em>';$('description').textContent=win?`${kills} possessed enemies defeated · ${Math.floor(time/60)}m ${Math.floor(time%60)}s. We could not save the director. The laboratory is finally safe. You take her seat. The adventure continues.`:'The lab is still under demonic control. Try again.';$('play').textContent='TRY AGAIN →';$('hint').textContent='ONE MORE TRY. ONE MORE CHANCE.'}
function verticalHit(e){const d=Math.hypot(e.x-p.x,e.y-p.y),height=e.type===3?3.3:e.type===2?2.2:1.65,aim=p.z+1.05+Math.tan(p.pitch)*d;return aim>e.z-.08&&aim<e.z+height}
function ammoSlot(index=weapon){return WEAPONS[index].ammoIndex??index}
function selectWeapon(index){if(!owned[index]){tell(WEAPONS[index].name+' — find this weapon first.');return}weapon=index;hud()}
function hitEnemy(e,damage){if(e.hp<=0||(e.type===3&&!bossAwake))return;e.hp-=damage;e.hit=.15;bloodBurst(e,e.hp<=0);combatAudio.impact();if(e.hp<=0){kills++;killQuip()}}
function launchProjectile(w){const cp=Math.cos(p.pitch),sp=Math.sin(p.pitch);playerShots.push({x:p.x+Math.cos(p.a)*.28,y:p.y+Math.sin(p.a)*.28,z:p.z+1.05,dx:Math.cos(p.a)*cp*w.speed,dy:Math.sin(p.a)*cp*w.speed,dz:sp*w.speed,kind:w.projectile,damage:w.damage,life:7,sourceYaw:p.a});}
function shoot(){
 if(mode!=='playing'||cooldown>0||charging)return;
 const w=WEAPONS[weapon],cost=w.cost??1,slot=ammoSlot();
 if(cost&&ammo[slot]<cost){tell('Out of '+(weapon===6?'cells (40 needed)':'ammo')+' — switch weapons [1–7]');cooldown=.3;return}
 ammo[slot]-=cost;cooldown=w.delay;flash=weapon===3?.07:weapon===2?.08:.14;combatAudio.shot(weapon);
 if(w.projectile){if(weapon===6){charging={remaining:.65,weapon:6};tell('BFG CHARGING…')}else launchProjectile(w);return}
 const targets=enemies.filter(e=>e.hp>0&&(e.type!==3||bossAwake)&&Math.hypot(e.x-p.x,e.y-p.y)<(w.range??60)&&verticalHit(e)&&line(p.x,p.y,e.x,e.y,p.z+1.05,e.z+.85)&&Math.abs(angle(Math.atan2(e.y-p.y,e.x-p.x)-p.a))<w.cone+.12/Math.max(.1,Math.hypot(e.x-p.x,e.y-p.y))).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));
 shotMarks(Math.min(w.range??60,targets.length?Math.hypot(targets[0].x-p.x,targets[0].y-p.y):60));
 for(let e of targets.slice(0,weapon===1?3:1))hitEnemy(e,weapon===1?Math.max(30,w.damage-Math.hypot(e.x-p.x,e.y-p.y)*8):w.damage);
}
function explodeShot(s,direct=null){
 explosions.push({x:s.x,y:s.y,z:s.z,kind:s.kind,life:s.kind==='bfg'?.65:.4,maxLife:s.kind==='bfg'?.65:.4});
 if(s.kind==='plasma'){if(direct)hitEnemy(direct,s.damage);return}
 const radius=s.kind==='bfg'?6:3.2;
 for(let e of enemies){if(e.hp<=0)continue;const d=Math.hypot(e.x-s.x,e.y-s.y,e.z+1-s.z);if(d<radius&&(e===direct||line(s.x,s.y,e.x,e.y,s.z,e.z+1)))hitEnemy(e,s.damage*Math.max(.1,1-d/radius)+(e===direct&&s.kind==='rocket'?120:0))}
 if(s.kind==='bfg')for(let e of enemies){const d=Math.hypot(e.x-s.x,e.y-s.y);if(e.hp>0&&d<14&&Math.abs(angle(Math.atan2(e.y-s.y,e.x-s.x)-s.sourceYaw))<1.2&&line(s.x,s.y,e.x,e.y,s.z,e.z+1))hitEnemy(e,180)}
 if(s.kind==='rocket'){const d=Math.hypot(p.x-s.x,p.y-s.y,p.z+1-s.z);if(d<radius&&line(s.x,s.y,p.x,p.y,s.z,p.z+1))damage(85*(1-d/radius))}
 tone(s.kind==='bfg'?50:70,.35,'sawtooth',.15);
}
function updatePlayerShots(dt){
 if(charging){charging.remaining-=dt;if(charging.remaining<=0){launchProjectile(WEAPONS[charging.weapon]);charging=null;flash=.3;tone(180,.4,'sawtooth',.1)}}
 for(let s of playerShots){s.life-=dt;if(s.life<=0){s.dead=true;continue}const steps=Math.max(1,Math.ceil(Math.hypot(s.dx,s.dy,s.dz)*dt/.08));for(let n=0;n<steps&&!s.dead;n++){
  const nx=s.x+s.dx*dt/steps,ny=s.y+s.dy*dt/steps,nz=s.z+s.dz*dt/steps;
  if(solid(nx,ny)||propBlocks(nx,ny)||nz<.06||nz>ceilingAt(nx,ny)){addMark(traceSurface(s.x,s.y,s.z,s.dx,s.dy,s.dz,.2),s.kind==='plasma'?'energyburn':'scorch',s.kind==='bfg'?1:s.kind==='rocket'?.6:.23);explodeShot(s);s.dead=true;break}
  s.x=nx;s.y=ny;s.z=nz;
  const target=enemies.find(e=>e.hp>0&&(e.type!==3||bossAwake)&&Math.hypot(e.x-nx,e.y-ny)<(e.type===3?.7:.4)&&nz>=e.z&&nz<=e.z+(e.type===3?3.3:e.type===2?2.2:1.65));
  if(target){explodeShot(s,target);s.dead=true}
 }}playerShots=playerShots.filter(s=>!s.dead);for(let e of explosions)e.life-=dt;explosions=explosions.filter(e=>e.life>0);
}
function enemySprite(e){const view=Math.atan2(p.y-e.y,p.x-e.x),relative=angle(view-e.a);const direction=(Math.round(relative/(Math.PI/2))+4)%4;const frame=e.moving?Math.floor(e.walk*2)%2:0;return 'enemy'+e.type+'_'+direction+'_'+frame}
function bloodBurst(e,dead){const d=Math.hypot(e.x-p.x,e.y-p.y),height=clamp(p.z+1.05+Math.tan(p.pitch)*d,e.z+.3,e.z+(e.type===2?1.9:1.45));for(let i=0;i<(dead?30:14);i++){let a=Math.random()*Math.PI*2,s=.4+Math.random()*1.8;particles.push({x:e.x,y:e.y,z:height,vx:Math.cos(a)*s,vy:Math.sin(a)*s,vz:.5+Math.random()*2,size:.025+Math.random()*.055,life:1.7})}splats.push({x:e.x,y:e.y,base:e.z+.012,size:dead?.8:.4,life:Infinity});particles=particles.slice(-240);for(let i=0;i<10;i++){let a=Math.atan2(e.y-p.y,e.x-p.x)+(i-5)*.24;addMark(traceSurface(e.x,e.y,height,Math.cos(a),Math.sin(a),(i%3-1)*.18,2.4),'bloodstain',.2+Math.random()*.3)}}
function killQuip(){if(time-lastQuip<4.5)return;lastQuip=time;quipIndex=(quipIndex+1)%4;quipTimer=3;$('quip').textContent='“'+killLines[quipIndex]+'”';combatAudio.say(quipIndex)}
function updateBlood(dt){for(let b of particles){b.life-=dt;b.vz-=5.5*dt;const dx=b.vx*dt,dy=b.vy*dt,dz=b.vz*dt,hit=traceSurface(b.x,b.y,b.z,dx,dy,dz,Math.hypot(dx,dy,dz)+.01);if(hit){addMark(hit,'bloodstain',b.size*5);b.life=0;continue}b.x+=dx;b.y+=dy;b.z+=dz;if(b.z<=.025){splats.push({x:b.x,y:b.y,base:.012,size:b.size*3,life:Infinity});b.life=0}}particles=particles.filter(b=>b.life>0);quipTimer=Math.max(0,quipTimer-dt);if(!quipTimer)$('quip').textContent=''}
function facingSecret(){return secretDoors.find(d=>!d.opened&&!d.opening&&Math.hypot(p.x-d.x-.5,p.y-d.y-.5)<1.6&&Math.abs(angle(Math.atan2(d.y+.5-p.y,d.x+.5-p.x)-p.a))<.65&&Math.abs(p.pitch)<.75)}
function updateSecrets(dt){for(let d of secretDoors){if(!d.opening)continue;d.remaining-=dt;if(d.remaining<=0){d.opening=false;d.opened=true;secretsFound++;for(let [x,y]of d.cells)setCell(x,y,'.');renderer?.rebuildWorld(level,floorAt,ceilingAt);tell(`Secret passage discovered — ${secretsFound} / 2`)}}$('interact').textContent=mode==='playing'&&facingSecret()?'[E] Open concealed service panel':''}
function interact(){
 const secret=facingSecret();if(secret){secret.opening=true;secret.remaining=.7;combatAudio.stoneDoor();tell('Opening concealed service passage…');return}
 const door=closestOfficeDoor(p);if(door&&!door.open){openOfficeDoor(door);renderer?.rebuildWorld(level,floorAt,ceilingAt);combatAudio.stoneDoor();tell(door.label+' — OPEN');return}
 activateSeals();
}
function openDoor(y,x1,x2){for(let x=x1;x<=x2;x++)setCell(x,y,'.');renderer?.rebuildWorld(level,floorAt,ceilingAt);combatAudio.stoneDoor()}
function activateSeals(){
 for(let i=0;i<seals.length;i++){let s=seals[i];if(!s.on||Math.hypot(s.x-p.x,s.y-p.y)>.8||(i===2&&stage<2))continue;s.on=false;tone(340,.5,'triangle',.15);tell(s.label+' — SYSTEM ONLINE')}
 if(stage===0&&!seals[0].on&&!seals[1].on){stage=1;openDoor(34,16,22);tell('BUILDING B SECURED. Cross the courtyard to Building A.')}
 if(stage===1&&p.y<34){stage=2;openDoor(14,16,22);tell('CAMPUS COURTYARD — Building A entrance ahead.')}
 if(stage===2&&!seals[2].on){stage=3;openDoor(8,18,20);tell('CONTAINMENT RELEASED. The director is in the north chamber.')}
 if(stage===3&&p.y<8&&!bossAwake){bossAwake=true;startBossEntrance();return}
 if(bossAwake&&!finalWave&&enemies.find(e=>e.type===3).hp<=0){finalWave=true;finish(true)}
}
function damage(n){p.hp=Math.max(0,p.hp-n);hurt=.45;tone(55,.18,'sawtooth',.12);if(!p.hp)finish(false)}
function collectItems(){
 const weaponItems={heavy:2,chainsaw:3,rocket:4,plasma:5,bfg:6},loads={2:180,3:0,4:12,5:100,6:120};
 for(let i of items){if(i.used||Math.hypot(i.x-p.x,i.y-p.y)>.6)continue;if(i.type==='health'&&p.hp===100)continue;i.used=true;
  if(i.type in weaponItems){let index=weaponItems[i.type];owned[index]=true;if(index===2)ownsHeavy=true;ammo[ammoSlot(index)]+=loads[index];weapon=index;tell(WEAPONS[index].name+' ACQUIRED! ['+(index+1)+']')}
  else if(i.type==='health'){p.hp=Math.min(100,p.hp+35);tell('Health +35')}
  else if(i.type==='cells'){ammo[5]+=60;tell('Energy cells +60')}
  else if(i.type==='rockets'){ammo[4]+=6;tell('Rockets +6')}
  else{ammo[0]+=24;ammo[1]+=8;if(owned[2])ammo[2]+=60;if(owned[4])ammo[4]+=3;if(owned[5]||owned[6])ammo[5]+=30;tell('Ammunition replenished')}
  tone(480,.16,'triangle');
 }
}
function update(dt){time+=dt;cooldown=Math.max(0,cooldown-dt);flash=Math.max(0,flash-dt);hurt=Math.max(0,hurt-dt);notice-=dt;if(notice<=0)$('message').textContent='';let f=(keys.w||keys.z||mouse.right?1:0)-(keys.s?1:0),r=(keys.d?1:0)-(keys.a||keys.q?1:0),speed=(keys.shift?4.3:3.1)*dt/Math.max(1,Math.hypot(f,r));p.a=angle(p.a+((keys.arrowright?1:0)-(keys.arrowleft?1:0))*dt*2);move(p,(Math.cos(p.a)*f-Math.sin(p.a)*r)*speed,(Math.sin(p.a)*f+Math.cos(p.a)*r)*speed);p.eyeZ+=(p.z-p.eyeZ)*(1-Math.exp(-dt*14));p.pitch=clamp(p.pitch+((keys.arrowup?1:0)-(keys.arrowdown?1:0))*dt*1.3,-1.35,1.35);updateBlood(dt);updateSecrets(dt);updateOfficeDoors(dt);updatePlayerShots(dt);activateSeals();if(mode!=='playing')return;const nearDoor=closestOfficeDoor(p);if(nearDoor&&!nearDoor.open)$('interact').textContent='[E] Open '+nearDoor.label.toLowerCase();if(keys[' ']||mouse.left)shoot();
 for(let e of enemies){e.moving=false;if(e.hp<=0||(e.type===3&&!bossAwake))continue;e.hit=Math.max(0,e.hit-dt);e.cd-=dt;let d=Math.hypot(p.x-e.x,p.y-e.y),visible=line(e.x,e.y,p.x,p.y,e.z+1.05,p.z+1.05);if(d<12&&visible){let a=Math.atan2(p.y-e.y,p.x-e.x);e.a=a;if(d>((e.type===1||e.type===3)?3:.75)){const ox=e.x,oy=e.y;move(e,Math.cos(a)*dt*[1.4,.7,.7,.85][e.type],Math.sin(a)*dt*[1.4,.7,.7,.85][e.type]);e.moving=Math.hypot(e.x-ox,e.y-oy)>.001;e.walk+=Math.hypot(e.x-ox,e.y-oy)*2}if(e.cd<=0){if(e.type===1||e.type===3){let z=e.z+1.1,dz=p.z+1.05-z,length=Math.hypot(d,dz);shots.push({x:e.x,y:e.y,z,dx:Math.cos(a)*d/length*3.5,dy:Math.sin(a)*d/length*3.5,dz:dz/length*3.5});e.cd=e.type===3?(e.hp<900?.6:1.1):2.3}else if(d<1&&Math.abs(e.z-p.z)<.6){damage(e.type===2?22:9);e.cd=.95}}}else if(e.type!==3){e.patrol-=dt;if(e.patrol<=0){e.a=angle(e.a+Math.PI/2);e.patrol=2+Math.random()*2}const ox=e.x,oy=e.y;move(e,Math.cos(e.a)*dt*.3,Math.sin(e.a)*dt*.3);e.moving=Math.hypot(e.x-ox,e.y-oy)>.001;e.walk+=Math.hypot(e.x-ox,e.y-oy)*2}}
 for(let s of shots){s.x+=s.dx*dt;s.y+=s.dy*dt;s.z+=s.dz*dt;if(solid(s.x,s.y)||s.z<floorAt(s.x,s.y)+.05||s.z>ceilingAt(s.x,s.y)){addMark(traceSurface(s.x-s.dx*dt,s.y-s.dy*dt,s.z-s.dz*dt,s.dx,s.dy,s.dz,Math.hypot(s.dx,s.dy,s.dz)*dt+.1),'energyburn',.2);s.dead=true}if(Math.hypot(s.x-p.x,s.y-p.y)<.3&&Math.abs(s.z-(p.z+1))<.7){damage(bossAwake?15:12);s.dead=true}}shots=shots.filter(s=>!s.dead);collectItems();if(finalWave)gateProgress=Math.min(1,gateProgress+dt*.8);hud();
}
function hud(){$('health').innerHTML=Math.ceil(p.hp)+' <i>%</i>';$('healthbar').style.width=p.hp+'%';$('ammo').textContent=weapon===3?'∞':ammo?.[ammoSlot()]??0;$('weapon').textContent=WEAPONS[weapon].name;$('heavyhint').textContent='[3] HEAVY · [4] SAW · [5] ROCKET · [6] PLASMA · [7] BFG';$('weaponstrip').innerHTML=WEAPONS.map((w,i)=>'<span class="'+(i===weapon?'equipped ': '')+(owned[i]?'available':'locked')+'">['+(i+1)+'] '+w.name+'</span>').join('');$('kills').textContent=kills+' POSSESSED ENEMIES DEFEATED';$('seals').textContent=seals.map(s=>s.on?'◇':'◆').join(' ');$('secretcount').textContent=bossAwake?'DIRECTOR: '+Math.max(0,Math.ceil(enemies.find(e=>e.type===3).hp))+' / 1800 HP':secretsFound+' / 2 SECRETS FOUND';$('timer').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0');$('status').textContent=['RESTORE TWO SYSTEMS IN BUILDING B','CROSS THE CAMPUS COURTYARD','OVERRIDE CONTAINMENT IN BUILDING A','DEFEAT THE POSSESSED DIRECTOR'][stage];$('sector').textContent=p.y>=34?'BUILDING B · RESEARCH WING':p.y>=15?'SAINT-PRIEST · CAMPUS COURTYARD':p.y<8?'BUILDING A · DIRECTOR’S CHAMBER':'BUILDING A · ROBOTICS & ADMINISTRATION';$('damage').style.opacity=hurt*.65}
function sprite(type){let c=document.createElement('canvas');c.width=c.height=64;let g=c.getContext('2d');const rect=(color,x,y,w,h)=>{g.fillStyle=color;g.fillRect(x,y,w,h)};if(typeof type==='number'){let color=['#ae4327','#814a58','#703124'][type];rect('#271713',15,52,13,10);rect('#271713',36,52,13,10);rect(color,16,25,32,29);rect(color,8,31,10,20);rect(color,46,31,10,20);rect('#e0b787',8,48,8,5);rect('#e0b787',48,48,8,5);rect(color,21,12,22,20);rect('#d0b49a',17,3,6,14);rect('#d0b49a',41,3,6,14);rect('#5b201b',24,30,16,19);rect('#f9b62b',24,19,5,4);rect('#f9b62b',35,19,5,4);rect('#160b09',26,27,12,4);rect('#efcca0',28,27,3,5);rect('#efcca0',34,27,3,5);if(type===2){rect('#caa88b',12,23,8,10);rect('#caa88b',44,23,8,10);rect('#ee6121',27,35,10,8)}if(type===1){rect('#ef692d',4,39,9,9);rect('#ffde73',6,41,5,5)}}else if(type==='seal'){g.strokeStyle='#f56a35';g.lineWidth=3;g.beginPath();g.arc(32,32,22,0,Math.PI*2);g.stroke();g.beginPath();for(let n=0;n<6;n++){let a=-Math.PI/2+n*4*Math.PI/5;let x=32+Math.cos(a)*19,y=32+Math.sin(a)*19;n?g.lineTo(x,y):g.moveTo(x,y)}g.stroke()}else if(type==='portal'){rect('#3c291e',8,2,48,62);rect('#5d5141',12,4,40,60);rect('#120d1c',18,10,28,54);rect('#ad4dd8',21,13,22,51);rect('#efd6ff',27,18,10,46)}else if(type==='fire'){rect('#d82e12',20,20,24,24);rect('#ff9b26',24,24,16,16);rect('#fff5aa',28,28,8,8)}else{rect(type==='health'?'#d3c6a5':'#847047',16,30,32,24);if(type==='health'){rect('#b13522',28,33,8,18);rect('#b13522',23,38,18,8)}else{rect('#e8b65b',21,34,5,13);rect('#e8b65b',30,34,5,13);rect('#e8b65b',39,34,5,13)}}return c}
const sprites={0:sprite(0),1:sprite(1),2:sprite(2),seal:sprite('seal'),portal:sprite('portal'),fire:sprite('fire'),health:sprite('health'),ammo:sprite('ammo'),secret:sprite('ammo')};
function labSprite(kind,label=''){
 const c=document.createElement('canvas');c.width=256;c.height=256;let g=c.getContext('2d');
 if(kind==='sign'){c.width=512;c.height=128;g.fillStyle='#102d40';g.fillRect(0,0,512,128);g.strokeStyle='#6be2ec';g.lineWidth=6;g.strokeRect(3,3,506,122);g.fillStyle='#e9f8ff';g.font='bold 32px monospace';g.textAlign='center';g.fillText(label,256,76)}
 if(kind==='desk'){g.fillStyle='#647b89';g.fillRect(5,150,246,22);g.fillRect(18,170,16,86);g.fillRect(220,170,16,86);g.fillStyle='#0e1827';g.fillRect(75,50,112,88);g.fillStyle='#4ee8c3';g.fillRect(82,58,98,65);g.fillStyle='#254c52';for(let y=65;y<115;y+=12)g.fillRect(90,y,70,4);g.fillStyle='#aab9bd';g.fillRect(119,135,23,18)}
 if(kind==='server'){g.fillStyle='#182a39';g.fillRect(55,5,146,250);for(let y=20;y<245;y+=35){g.fillStyle='#526674';g.fillRect(65,y,125,25);g.fillStyle='#6fffb0';g.fillRect(73,y+8,9,9);g.fillStyle='#172733';g.fillRect(90,y+7,90,4)}}
 if(kind==='tree'){g.fillStyle='#55453c';g.fillRect(115,90,25,166);g.fillStyle='#234f45';for(let [x,y,r]of [[80,75,65],[160,65,65],[125,35,55]]){g.beginPath();g.arc(x,y,r,0,7);g.fill()}}
 if(kind==='seal'){g.fillStyle='#253746';g.fillRect(40,40,176,176);g.strokeStyle='#58ffde';g.lineWidth=12;g.strokeRect(44,44,168,168);g.fillStyle='#58ffde';g.font='bold 48px monospace';g.textAlign='center';g.fillText('SYS',128,142)}
 return c;
}
for(let kind of ['desk','server','tree','seal'])sprites[kind]=labSprite(kind);
// Canvas-native mechanical panels, supplies and energy effects complement generated weapon art.
function effectSprite(kind){const c=document.createElement('canvas');c.width=c.height=128;const g=c.getContext('2d');if(kind==='door'){g.fillStyle='#846d4c';g.fillRect(0,0,128,128);g.fillStyle='#233d51';g.fillRect(18,10,92,53);g.fillStyle='#b0def0';g.fillRect(24,16,80,40);g.fillStyle='#cab77b';g.fillRect(99,77,12,5);g.strokeStyle='#4b3e2d';g.lineWidth=5;g.strokeRect(3,3,122,122)}else if(kind==='rockets'||kind==='cells'){g.fillStyle='#273b4a';g.fillRect(16,35,96,84);g.fillStyle=kind==='cells'?'#60e6ff':'#d2a77a';for(let x=25;x<105;x+=24)g.fillRect(x,43,16,62)}else{const color=kind==='plasma'?'#31aaff':kind==='bfg'?'#76ff34':kind==='rocket'?'#ff9c3c':'#ff702e';const glow=g.createRadialGradient(64,64,2,64,64,61);glow.addColorStop(0,'#fff');glow.addColorStop(.2,color);glow.addColorStop(1,color+'00');g.fillStyle=glow;g.fillRect(0,0,128,128)}return c}
for(let kind of ['door','rockets','cells','plasma','bfg','rocket','blast'])sprites[kind]=effectSprite(kind);
const roomSigns=[[19.5,51,'BUILDING B'],[8,41,'COMPUTING'],[29,41,'MICROELECTRONICS'],[19.5,33.5,'BUILDING B'],[19.5,15.5,'BUILDING A'],[7,12,'ROBOTICS'],[29,12,'ADMINISTRATION'],[19.5,7,'DIRECTOR']];
roomSigns.forEach((r,i)=>sprites['sign'+i]=labSprite('sign',r[2]));
function rOutdoorSign(i){return i===3||i===4}
function furnishings(){return [...roomSigns.map(([x,y],i)=>({x,y,kind:'sign'+i,height:.6,width:rOutdoorSign(i)?4:2.5,base:2.7})),...[[7,52],[30,52],[8,46],[30,46],[11.5,39],[28,39],[7,11],[31,11],[14,3],[25,3]].map(([x,y])=>({x,y,kind:'desk',height:1.3,width:1.6,base:0})),...[[5.5,36.5],[33,36.5],[33,44]].map(([x,y])=>({x,y,kind:'server',height:2.5,width:1.3,base:0}))]}
function render(){ctx.clearRect(0,0,W,H);if(!renderer?.ready)return;let objects=[...furnishings(),...persistentMarks(),...secretDoors.filter(d=>!d.opened).map(d=>({x:d.hintX,y:d.hintY,kind:'crack',wallDecal:true,height:.45,base:floorAt(d.hintX,d.hintY)+1.05})),...splats.map(b=>({...b,kind:'bloodstain',ground:true,opacity:1})),...particles.map(b=>({...b,kind:'blood',height:b.size,base:b.z})),...enemies.filter(e=>e.hp>0).map(e=>({...e,kind:enemySprite(e),width:e.type===3?2.9:e.type===2?1.8:1.25,height:e.type===3?3.3:e.type===2?2.2:1.65,base:e.z+(e.moving?Math.sin(e.walk*Math.PI*2)*.025:0)})),...items.filter(i=>!i.used).map(i=>({...i,kind:['chainsaw','rocket','plasma','bfg'].includes(i.type)?'pickup'+i.type:i.type,height:['heavy','chainsaw','rocket','plasma','bfg'].includes(i.type)?.65:.45,width:['heavy','chainsaw','rocket','plasma','bfg'].includes(i.type)?1:.45,base:floorAt(i.x,i.y)})),...seals.map(s=>({...s,kind:'seal',ground:true,size:1.25,base:floorAt(s.x,s.y)+.015,active:s.on,opacity:s.on?1:.25})),...shots.map(s=>({...s,kind:'fire',base:s.z-.16})),...playerShots.map(s=>({...s,kind:s.kind,height:s.kind==='bfg'?1.1:s.kind==='rocket'?.3:.24,base:s.z-(s.kind==='bfg'?.55:.12)})),...explosions.map(e=>({...e,kind:e.kind==='bfg'?'bfg':'blast',height:(e.kind==='bfg'?5:2.5)*(1-e.life/e.maxLife+.3),base:Math.max(0,e.z-.8),opacity:e.life/e.maxLife}))];renderer.draw(p,objects,time);let moving=mode==='playing'&&(mouse.right||keys.w||keys.z||keys.s||keys.a||keys.q||keys.d),bob=moving?Math.sin(time*10)*5:0,recoil=flash/.14,size=WEAPONS[weapon].size,cx=W*.5+35,top=H*.54+bob+recoil*(weapon===2?12:26);ctx.imageSmoothingEnabled=true;ctx.drawImage(renderer.weapons[weapon],cx-size/2,top,size,size);if(flash>0&&weapon!==3){let mx=cx,my=top+size*.025;ctx.save();ctx.globalCompositeOperation='screen';let fire=ctx.createRadialGradient(mx,my,2,mx,my,weapon===2?95:80);fire.addColorStop(0,'#ffffe5');fire.addColorStop(.25,weapon===5?'#67ccfff0':weapon===6?'#76ff67f0':'#ffd65df0');fire.addColorStop(.6,weapon===5?'#167cff90':weapon===6?'#16ff4190':'#f7632190');fire.addColorStop(1,'#ff450000');ctx.fillStyle=fire;ctx.fillRect(mx-95,my-95,190,190);ctx.restore()}if(charging){ctx.fillStyle='#6dff5a88';ctx.fillRect(0,H-5,W*(1-charging.remaining/.65),5)}if(bossAwake){const boss=enemies.find(e=>e.type===3);ctx.fillStyle='#130f20dd';ctx.fillRect(260,22,440,34);ctx.fillStyle='#ae4be8';ctx.fillRect(265,43,430*Math.max(0,boss.hp)/1800,6);ctx.fillStyle='#fff';ctx.font='14px monospace';ctx.textAlign='center';ctx.fillText('THE DIRECTOR'+(boss.hp<900?' · ENRAGED':''),480,38);ctx.textAlign='left'}if(mapShown)drawMap()}
function drawMap(){const scale=4.5,ox=12,oy=12;ctx.fillStyle='#0c0808ef';ctx.fillRect(8,8,WORLD_WIDTH*scale+8,WORLD_DEPTH*scale+8);for(let y=0;y<level.length;y++)for(let x=0;x<level[y].length;x++){ctx.fillStyle=hiddenMapCell(x,y)?'#0c0808':cellAt(x,y)==='D'?'#dcbd67':solid(x,y)?'#71838e':outdoor(x,y)?'#316347':'#223746';ctx.fillRect(ox+x*scale,oy+y*scale,scale-.5,scale-.5)}for(let s of seals){ctx.fillStyle=s.on?'#f47c32':'#685441';ctx.fillRect(ox+s.x*scale-2,oy+s.y*scale-2,4,4)}ctx.fillStyle=finalWave?'#f86323':'#674131';ctx.fillRect(ox+exit.x*scale-3,oy+exit.y*scale-3,6,6);ctx.fillStyle='#ffebad';ctx.beginPath();ctx.arc(ox+p.x*scale,oy+p.y*scale,3,0,7);ctx.fill();ctx.strokeStyle='#ffebad';ctx.beginPath();ctx.moveTo(ox+p.x*scale,oy+p.y*scale);ctx.lineTo(ox+(p.x+Math.cos(p.a))*scale,oy+(p.y+Math.sin(p.a))*scale);ctx.stroke()}
function pause(){if(mode!=='playing')return;mode='paused';combatAudio.stopVoice();combatAudio.setGameplayActive(false);keys={};mouse={left:false,right:false};$('veil').style.display='flex';$('crosshair').style.display='none';$('interact').textContent='';document.querySelector('.eyebrow').textContent='CATCH YOUR BREATH.';document.querySelector('h1').innerHTML='HELL<br><em>CAN WAIT</em>';$('description').textContent='The research wings are waiting. Your mission continues.';$('play').textContent='RESUME →';$('hint').textContent='USE ARROW KEYS IF MOUSE CAPTURE IS UNAVAILABLE'}
let introSeen=false;
function initAudio(){if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}audio?.resume();combatAudio.init(audio);combatAudio.setMuted(!sound)}
function beginGameplay(){combatAudio.stopCinematicMusic();mode='playing';$('veil').style.display='none';$('crosshair').style.display='block';keys={};mouse={left:false,right:false};combatAudio.setGameplayActive(true);try{canvas.requestPointerLock?.()?.catch(()=>tell('Mouse capture unavailable: use arrow keys.'))}catch{tell('Use arrow keys to look around.')}tell(bossAwake?'THE POSSESSED DIRECTOR — defeat her!':'Building B: restore network and power at the glowing terminals. M: map.')}
function introBriefing(){combatAudio.stopCinematicMusic();introSeen=true;mode='briefing';$('veil').style.display='flex';$('crosshair').style.display='none';document.querySelector('.eyebrow').textContent='ONE MINUTE LATER · BUILDING B';document.querySelector('h1').innerHTML='LIBERATE<br><em>THE LAB</em>';$('description').textContent='The director is possessed. Restore network isolation and power in Building B, cross the campus, then confront her in Building A.';$('play').textContent='ENTER BUILDING B →';$('hint').textContent='[E] OFFICE DOORS & SECRET PANELS · [1–7] WEAPONS · [M] MAP';$('play').focus()}
function cinemaSound(cue){if(!sound||!audio)return;if(cue==='office')tone(135,.5,'sine',.015);if(cue==='signal'){tone(430,.45,'triangle',.045);tone(52,1.1,'sine',.07)}if(cue==='change'){combatAudio.stoneDoor();tone(95,1.2,'sawtooth',.06)}if(cue==='reveal'){combatAudio.specialShot(6);tone(63,.8,'sawtooth',.09)}if(cue==='end')tone(110,.65,'triangle',.045)}
const opening=new OpeningCinema({canvas:$('cinema'),container:$('cinematic'),caption:$('cinema-caption'),chapter:$('cinema-chapter'),skip:$('skip-intro'),onComplete:cinemaComplete,onSkip:cinemaSkip,sound:cinemaSound});
function startBossEntrance(){mode='bossintro';keys={};mouse={left:false,right:false};combatAudio.stopVoice();combatAudio.setGameplayActive(false);document.exitPointerLock?.();$('crosshair').style.display='none';opening.start('boss');combatAudio.startCinematicMusic('boss')}
function startEnding(){mode='ending';keys={};mouse={left:false,right:false};charging=null;combatAudio.stopVoice();combatAudio.setGameplayActive(false);document.exitPointerLock?.();$('crosshair').style.display='none';$('veil').style.display='none';opening.start('ending');combatAudio.startCinematicMusic('ending')}
function bossReady(){combatAudio.stopCinematicMusic();mode='bossready';$('veil').style.display='flex';document.querySelector('.eyebrow').textContent='BUILDING A · THE FINAL CONFRONTATION';document.querySelector('h1').innerHTML='FACE<br><em>THE DIRECTOR</em>';$('description').textContent='She is waiting. There is no turning back.';$('play').textContent='FIGHT THE DIRECTOR →';$('hint').textContent='[1–7] CHOOSE YOUR WEAPON';$('play').focus()}
function cinemaComplete(){if(mode==='ending'){combatAudio.stopCinematicMusic();finish(true)}else if(mode==='bossintro')bossReady();else introBriefing()}
function cinemaSkip(){if(mode==='ending'){combatAudio.stopCinematicMusic();finish(true)}else if(mode==='bossintro'){initAudio();beginGameplay()}else{introSeen=true;initAudio();beginGameplay()}}
$('play').onclick=()=>{initAudio();if(mode==='paused'||mode==='briefing'||mode==='bossready'){beginGameplay();return}reset();if(!introSeen){mode='intro';$('veil').style.display='none';$('crosshair').style.display='none';combatAudio.setGameplayActive(false);opening.start();combatAudio.startCinematicMusic('intro')}else beginGameplay()};
$('music').onclick=()=>{combatAudio.setMusicEnabled(!combatAudio.musicEnabled);$('music').textContent='MUSIC: '+(combatAudio.musicEnabled?'ON':'OFF');$('music').setAttribute('aria-pressed',String(combatAudio.musicEnabled))};
$('voice').onclick=()=>{combatAudio.setVoiceEnabled(!combatAudio.voiceEnabled);$('voice').textContent='VOICE: '+(combatAudio.voiceEnabled?'ON':'OFF');$('voice').setAttribute('aria-pressed',String(combatAudio.voiceEnabled))};
$('sound').onclick=()=>{sound=!sound;combatAudio.setMuted(!sound);$('sound').textContent='SOUND: '+(sound?'ON':'OFF')};
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas)pause()});document.addEventListener('mousemove',e=>{if(mode==='playing'&&document.pointerLockElement===canvas){p.a=angle(p.a+e.movementX*.0025);p.pitch=clamp(p.pitch-e.movementY*.0025,-1.35,1.35)}});canvas.addEventListener('mousedown',e=>{if(mode!=='playing')return;e.preventDefault();if(e.button===0){mouse.left=true;shoot()}if(e.button===2)mouse.right=true});document.addEventListener('mouseup',e=>{if(e.button===0)mouse.left=false;if(e.button===2)mouse.right=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['intro','bossintro','ending'].includes(mode)){if(k==='escape'||k===' '||k==='enter'){e.preventDefault();opening.finish(true)}return}if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(mode==='playing'){if(['1','2','3','4','5','6','7'].includes(k))selectWeapon(Number(k)-1);if(k==='e'&&!e.repeat)interact();if(k==='m'&&!e.repeat)mapShown=!mapShown;if(k==='escape'){pause();document.exitPointerLock?.()}}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{pause();keys={};mouse={left:false,right:false}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
function frame(t){let dt=Math.min((t-last)/1000,.04);last=t;if(['intro','bossintro','ending'].includes(mode))opening.update(dt);else{if(mode==='playing')update(dt);render()}requestAnimationFrame(frame)}reset();$('play').disabled=true;$('play').textContent='LOADING THE LAB…';
try{renderer=new HellRenderer(canvas,level,floorAt,ceilingAt);Promise.all([renderer.load(sprites),opening.load()]).then(()=>{$('play').disabled=false;$('play').textContent='LIBERATE THE LAB →';requestAnimationFrame(frame)}).catch(showLoadError)}catch(e){showLoadError(e)}
function showLoadError(e){$('description').textContent=e.message;$('play').textContent='RELOAD';$('play').disabled=false;$('play').onclick=()=>location.reload()}
